import functools


def repeat(times):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            return [fn(*args, **kwargs) for _ in range(times)]

        return wrapper

    return deco


@repeat(3)
def beep(i):
    return f"beep {i}"


print(beep(1))

_registry = {}


def register(name):
    def deco(fn):
        _registry[name] = fn
        return fn

    return deco


@register("greet")
def greet():
    return "hi"


@register("bye")
def bye():
    return "bye"


print(sorted(_registry))
print(_registry["bye"]())

